const INSTRUCTIONS_CACHE_TTL_MS = 15 * 60 * 1000; // 15 minutes

/**
 * Upper bound, in bytes, for the default instructions of any tool profile.
 *
 * Some clients copy the server instructions into every tool definition. Codex code mode, for
 * example, ships the whole catalog in a single IPC frame capped at 64 MiB, so the cost of this text
 * is roughly `(tool count + 1) * instructions size`. Keep the default instructions short and serve
 * detailed workflow rules through get_capability_guidance instead of embedding them here.
 */
export const DEFAULT_INSTRUCTIONS_MAX_BYTES = 8 * 1024;

